import React from 'react';
import {
  LineChart, Line, XAxis, YAxis, Tooltip, CartesianGrid
} from 'recharts';
import { useTranslation } from 'react-i18next';

export default function LineChartComponent({ data, provinces }) {
  const { t } = useTranslation();
  // pivot data by date
  const dates = [...new Set(data.map(d => d.date))].sort();
  const chartData = dates.map(date => {
    const entry = { date };
    provinces.forEach(prov => {
      const pt = data.find(d => d.date === date && d.province === prov);
      entry[prov] = pt ? pt.value : null;
    });
    return entry;
  });

  return (
    <div>
      <h2>{t('line_chart_title', { type: data[0]?.type || '' })}</h2>
      <LineChart width={700} height={300} data={chartData}>
        <CartesianGrid strokeDasharray="3 3" />
        <XAxis dataKey="date" />
        <YAxis />
        <Tooltip />
        {provinces.map(prov => (
          <Line
            key={prov}
            type="monotone"
            dataKey={prov}
            name={prov}
            dot={false}
          />
        ))}
      </LineChart>
    </div>
  );
}
